		"\"Scope\" distinguishes between statutory holidays, organization-wide company holidays, and custom entries. Statutory holidays are usually full-day; in Switzerland some statutory days (e.g. Sechseläuten) are half-day and count as 0.5." : "\"Omfang\" skiller mellom lovpålagte helligdager, bedriftshelligdager i hele organisasjonen og egendefinerte poster. Lovpålagte helligdager er vanligvis heldags; i Sveits er noen lovpålagte dager (f.eks. Sechseläuten) halvdags og teller som 0,5.",
