		"An unfinished session from a previous day was closed automatically. Please verify your time entries list." : "En ufullført økt fra en tidligere dag ble avsluttet automatisk. Kontroller listen over tidsregistreringer.",
		"Anniversary mode needs an employment start date on each employee (Employees → person). People without a start date get no vacation entitlement until it is set. Carryover expiry below switches to “months after anniversary” automatically." : "Årsdagmodus krever en ansettelsesstartdato for hver ansatt (Ansatte → person). Personer uten startdato får ingen ferierett før den er satt. Utløp av restferie nedenfor bytter automatisk til «måneder etter årsdag».",
		"Annual entitlement" : "Årlig rett",
		"Annual hour pack + priority response — details in the offer \/ on our site." : "Årlig timepakke + prioritert svar — detaljer i tilbuddet \/ på nettstedet vårt.",
		"Annual hour packs — Small, Standard, or Premium — with priority email for your organisation. This is invoiceable service — not a donation. See packages on our support page." : "Årlige timepakker — Small, Standard eller Premium — med prioritert e-post for organisasjonen. Dette er fakturerbar tjeneste — ikke en donasjon. Se pakker på støttesiden.",
		"Annual leave left" : "Årlig orlov tilbake",
