		"Annual: %1$s d · Carryover: %2$s d" : "Årlig: %1$s d · Overføring: %2$s d",
		"Annual: %1$s h · Carryover: %2$s h" : "Årlig: %1$s t · Restferie: %2$s t",
		"Another PIN or badge change is still finishing for this employee or tablet. Wait a few seconds, then try again. If a badge scan is stuck, click “Cancel scan” — that always clears it." : "En annen PIN- eller badge-endring er fortsatt i ferd med å bli fullført for denne ansatte eller dette nettbrettet. Vent noen sekunder, og prøv deretter igjen. Hvis en badge-skanning sitter fast, klikk \"Avbryt skanning\" — det rydder den alltid.",
		"Another PIN or badge change is still finishing. Wait a few seconds, then try again. If a badge scan is stuck, click “Cancel scan” — that always clears it." : "En annen PIN- eller badge-endring er fortsatt i ferd med å bli fullført. Vent noen sekunder, og prøv deretter igjen. Hvis en badge-skanning sitter fast, klikk \"Avbryt skanning\" — det rydder den alltid.",
		"Another absence change is in progress on this account. Please wait a moment and try again." : "En annen fraværsendring pågår på denne kontoen. Vent litt og prøv igjen.",
