		"Are you sure you want to delete \"{name}\"?\n\nThis will permanently remove this work schedule. If any employees are using this schedule, you should assign them to a different schedule first.\n\nThis action cannot be undone." : "Er du sikker på at du vil slette «{name}»?\n\nDette fjerner arbeidsplanen permanent. Hvis noen medarbeidere bruker denne arbeidsplanen, bør du først tildele dem en annen arbeidsplan.\n\nDenne handlingen kan ikke angres.",
		"Are you sure you want to delete the team \"%s\"? Members and managers will be unassigned." : "Er du sikker på at du vil slette teamet «%s»? Medlemmer og ledere vil miste tilknytningen.",
