		"Are you sure you want to delete this work schedule?\n\nThis will permanently remove this schedule. If any employees are using this schedule, you should assign them to a different schedule first.\n\nThis action cannot be undone." : "Er du sikker på at du vil slette denne arbeidsplanen?\n\nDette fjerner arbeidsplanen permanent. Hvis noen medarbeidere bruker denne arbeidsplanen, bør du først tildele dem en annen arbeidsplan.\n\nDenne handlingen kan ikke angres.",
