		"Changes the hour Saldo only. Recorded working time stays unchanged. Negative hours reduce the balance (e.g. paid out); positive hours increase it (e.g. forgive undertime)." : "Endrer bare timesaldoen. Registrert arbeidstid forblir uendret. Negative timer reduserer saldoen (f.eks. utbetaling); positive timer øker den (f.eks. ettergivelse av undertid).",
		"Changes to existing entries" : "Endringer i eksisterende poster",
