		"Changing the country does not change the limit values under “Daily hours and rest periods” below — review them after switching. Nothing is saved until you select “Save all settings”." : "Bytte av land endrer ikke grenseverdiene under «Daglige timer og hvileperioder» nedenfor — gå gjennom dem etter byttet. Ingenting lagres før du velger «Lagre alle innstillinger».",
		"Changing the country updates working time rules for the whole organisation. Daily hour and rest limits you already set are kept — review them under Settings after switching." : "Bytte av land oppdaterer arbeidstidsregler for hele organisasjonen. Daglige time- og hvilegrenser allerede har satt, beholdes — gjennomgå dem under Innstillinger etter byttet.",
