		"Click \"Complete\" next to the entry below to finalise it with the time it was paused — required breaks are added automatically. You can also click \"Edit\" to set custom times." : "Klikk «Fullfør» ved siden av registreringen nedenfor for å ferdigstille den med tidspunktet den ble satt på pause — påkrevde pauser legges til automatisk. Du kan også klikke «Rediger» for å angi egne tider.",
