		"Confirm that people without a hire date will have no vacation until a start date is set." : "Bekreft at personer uten ansettelsesdato ikke har ferie før en startdato er satt.",
		"Confirm that this exact configuration has completed the documented legal review. Editing the draft afterwards requires a new review." : "Bekreft at nøyaktig denne konfigurasjonen har fullført den dokumenterte juridiske gjennomgangen. Å redigere utkastet etterpå krever en ny gjennomgang.",
