		"Control how entries that run across midnight appear in CSV and JSON exports." : "Styr hvordan registreringer som går over midnatt, vises i CSV- og JSON-eksporter.",
		"Control how long time-tracking records are kept before automated cleanup." : "Kontroller, hvor lenge tidsregistreringer oppbevares før automatisk opprydding.",
		"Control how the app handles your breaks." : "Styr hvordan appen håndterer pausene dine.",
		"Control iCal attachments and substitution emails when absences are approved." : "Styr iCal-vedlegg og vikar-e-poster når fravær godkjennes.",
		"Conversion factor for the days↔hours migration wizard only. Day-to-day vacation bookings use each employee’s working-time model (weekday schedule or model daily hours). This value is only a fallback when no model applies. Changing it later does not rewrite existing hour balances; converting back to days uses the factor from the last unit switch." : "Konverteringsfaktor bare for dager↔timer-veiviseren. Daglige feriebestillinger bruker personens arbeidstidsmodell (ukedagsplan eller modellens dagstimer). Bare reserved uten modell. Senere endring omskriver ikke eksisterende timesaldo; tilbake til dager bruker faktoren fra siste enhetsbytte.",
		"Convert all open vacation balances and absences to hours using %s hours per day? This cannot be undone without converting back." : "Konvertere alle åpne feriesaldoer og fravær til timer med %s timer per dag? Kan ikke angres uten å konvertere tilbake.",
		"Convert all open vacation balances back to days using %s hours per day (from the last conversion when available)? Partial-hour bookings become fractional days (for example 4 hours → 0.5 days)." : "Konvertere åpne feriesaldoer tilbake til dager med %s timer\/dag (fra siste konvertering hvis tilgjengelig)? Delvise timer blir brøkdeler av dager (f.eks. 4 timer → 0,5 dager).",
