		"Date ranges (e.g. school holidays) in which binding presence rules from working time models do not apply. Entered once per year; has no effect for models without presence rules." : "Datoområder (f.eks. skoleferier) hvor bindende fremmøteregler fra arbeidstidsmodeller ikke gjelder. Legges inn én gang per år; har ingen effekt for modeller uten fremmøteregler.",
