		"Decimal hours (5.5)" : "Desimaltimer (5,5)",
		"Decimal hours are allowed (e.g. 38.7 h\/week under a collective agreement). Overtime targets use this weekly total spread across your working days." : "Desimaltimer er tillatt (f.eks. 38,7 t\/uke i henhold til en tariffavtale). Mål for overtid bruker denne ukentlige total fordelt på dine arbeidsdager.",
		"Decline" : "Nedgang",
		"Decline substitution" : "Avvis vikar",
		"Declined by substitute" : "Avvist av stedfortreder",
		"Dedicated app administrators appear in the list together with Nextcloud admins. Use search to find colleagues, then tick them. After saving they can open Administration (and Manager) without Nextcloud admin rights. You cannot remove your own last app-admin seat — ask a Nextcloud admin if you need to step down." : "Dedikerte appadministratorer vises i listen sammen med Nextcloud-admins. Bruk søk for å finne kolleger, og huk av dem. Etter lagring kan de åpne Administrasjon (og Leder) uten Nextcloud-adminrettigheter. Du kan ikke fjerne din siste app-admin-plass selv — be en Nextcloud-admin hvis du må trekke deg.",
		"Dedicated app administrators appear in the list together with Nextcloud admins. Use search to find colleagues, then tick them. Changes take effect immediately after saving." : "Dedikerte app-administratorer vises i listen sammen med Nextcloud-administratorer. Bruk søk for å finne kolleger, og kryss dem deretter av. Endringer trer i kraft umiddelbart etter lagring.",
		"Deductions (subtract days)" : "Fradrag (trekk dager fra)",
		"Default" : "Standard",
		"Default daily working hours. Used for new employees until individual models are set." : "Standard daglig arbeidstid. Brukes for nye medarbeidere til individuelle modeller er satt.",
		"Default daily working hours. Used for new employees until individual models are set. Decimal hours are allowed (e.g. 7.7)." : "Standard daglig arbeidstid. Brukes for nye medarbeidere til individuelle modeller er satt. Desimaltimer er tillatt (f.eks. 7.7).",
		"Default daily working hours. Used for new employees until individual models are set. Decimal hours are allowed (e.g. 7.74)." : "Standard daglige arbeidstimer. Brukes for nye ansatte til individuelle modeller er satt. Desimaltimer er tillatt (f.eks. 7,74).",
		"Default fallback" : "Standard fallback",
		"Default federal state for holidays" : "Delstat som standard for helligdager",
		"Default federal state was saved." : "Standarddelstat ble lagret.",
		"Default is the next day that is not yet closed. Backdating requires an explicit choice." : "Standard er neste dag som ennå ikke er avsluttet. Tilbakedatering krever et eksplisitt valg.",
		"Default overlap: highest single percentage. Night window is editable. Templates are starters — not a legal guarantee." : "Standard ved overlapping: høyeste enkeltprosent. Nattevindu er redigerbart. Maler er startpunkter — ikke en juridisk garanti.",
		"Default paid break time" : "Standard betalt pausetid",
		"Default paid break time per day (minutes)" : "Standard betalt pausetid per dag (minutter)",
		"Default policy created." : "Standardpolicy opprettet.",
		"Default region for public holidays" : "Standardregion for helligdager",
		"Default region was saved." : "Standardregion ble lagret.",
		"Default work location" : "Standard arbeidssted",
		"Default working hours must be between 1 and 24" : "Standard arbeidstid må være mellom 1 og 24",
		"Defaults attached to a working time model (e.g. “30 hours \/ week”). Apply automatically to every employee with that model who has no individual or team rule." : "Standarder knyttet til en arbeidstidsmodell (f.eks. «30 timer\/uke»). Brukes automatisk for hver medarbeider med den modellen som ikke har noen individuell regel eller teamregel.",
		"Defaults to today. Pick a past or future date to see how the entitlement changes." : "Standard er i dag. Velg en tidligere eller fremtidig dato for å se hvordan rettigheten endres.",
		"Define additional absence types for your organisation" : "Definer flere fraværstyper for organisasjonen din",
		"Define additional leave entitlements and their quotas" : "Definer ytterligere permisjonsrettigheter og deres kvoter",
		"Define equivalent thresholds for undertime (negative balance)." : "Definer ekvivalente terskler for undertid (negativ saldo).",
		"Define for which absence types a substitute must be chosen before a request can be submitted." : "Definer for hvilke fraværstyper det skal velges en stedfortreder før en forespørsel kan sendes.",
		"Define how ArbeitszeitCheck validates bookings, handles break edge cases, and enforces legal limits." : "Definer hvordan ArbeitszeitCheck validerer bookinger, håndterer kanttilfeller for pauser og håndhever juridiske grenser.",
		"Define how business trips count towards the time account" : "Definer hvordan forretningsreiser teller på tidskontoen",
		"Define how many vacation days an employee is entitled to. Rules are evaluated top-down: a higher layer always wins. This page lets you see, edit, and simulate the full precedence chain." : "Definer hvor mange feriedager en ansatt har rett til. Regler vurderes ovenfra og ned: et høyere lag vinner alltid. Bruk denne siden til å se, redigere og simulere hele forrangskjeden.",
		"Define how many vacation days an employee is entitled to. Rules are evaluated top-down: a higher layer always wins. Use this page to view, edit, and simulate the full precedence chain." : "Definer hvor mange feriedager en ansatt har rett til. Regler vurderes ovenfra og ned: et høyere lag vinner alltid. Bruk denne siden til å se, redigere og simulere hele forrangskjeden.",
		"Define how many vacation days people get. A higher layer always wins. Edit organisation, model, and team defaults here; simulate any person." : "Angi hvor mange feriedager personer får. Et høyere lag vinner alltid. Rediger organisasjons-, modell- og teamstandarder her; simuler en hvilken som helst person.",
		"Define organisation-wide break rules here. Statutory minimum breaks always apply — these rules can only tighten them, never weaken them." : "Definer organisasjonsdekkende pauseregler her. Lovbestemte minimumspauser gjelder alltid — disse reglene kan bare skjerpe dem, aldri svekke dem.",
		"Define organizational units, assign members, and designate managers for approvals." : "Definer organisatoriske enheter, tildel medlemmer, og utpek ledere for godkjenninger.",
		"Define teams and assign members and managers. Managers can approve absences and time corrections for their team members. When enabled below, this replaces Nextcloud group-based manager resolution." : "Definer team og tildel medlemmer og ledere. Ledere kan godkjenne fravær og tidskorrigeringer for teammedlemmene sine. Når dette er aktivert nedenfor, erstatter det Nextclouds gruppebaserte lederoppløsning.",
		"Define teams, departments, or any organizational units in a flexible hierarchy. Assign members and managers. When enabled below, managers can approve absences and time corrections for their unit members." : "Definer team, avdelinger eller andre organisasjonsenheter i et fleksibelt hierarki. Tildel medlemmer og ledere. Når dette er aktivert nedenfor, kan ledere godkjenne fravær og tidskorrigeringer for enhetsmedlemmene sine.",
		"Define teams, departments, or other organizational units in a flexible hierarchy. Assign members and managers. If enabled below, managers can approve absences and time corrections for their units." : "Definer team, avdelinger eller andre organisatoriske enheter i et fleksibelt hierarki. Tildel medlemmer og ledere. Hvis det er aktivert nedenfor, kan ledere godkjenne fravær og tidskorrigeringer for enhetene sine.",
		"Define when overtime changes from green to yellow and yellow to red (hours)." : "Definer når overtid skifter fra grønn til gul og fra gul til rød (timer).",
		"Define when overtime changes from green to yellow and yellow to red." : "Definer, når overtid skifter fra grøn til gul og gul til rød.",
