		"Delete the absence type “{name}”? It is not used in any absence and will be removed permanently." : "Slett fraværstypen «{name}»? Den brukes ikke i noe fravær og fjernes permanent.",
		"Delete the absence type “{name}”? Types that are still in use are deactivated instead of deleted, so existing records keep working." : "Slett fraværstypen «{name}»? Typer som fortsatt er i bruk deaktiveres i stedet for å slettes, slik at eksisterende registreringer fortsatt fungerer.",
