		"Deleted." : "Slettet.",
		"Deletes eligible time entries older than the configured retention period and clears your personal settings. Recent time entries, absences, audit logs, and compliance records are kept where the law requires it. This cannot be undone." : "Sletter kvalifiserte tidsregistreringer eldre enn den konfigurerte oppbevaringsperioden og tømmer dine personlige innstillinger. Nylige registreringer, fravær, revisjonslogger og samsvarsoppføringer beholdes der loven krever det. Kan ikke angres.",
		"Deleting this unit will unassign all members and managers from it. Sub-teams must be handled separately." : "Hvis du sletter denne enheten, fjernes alle medlemmer og ledere fra den. Underteams må håndteres separat.",
		"Deleting this unit will unassign all members and managers." : "Sletting av denne enheten fjerner tildelingen av alle medlemmer og ledere.",
		"Deleting your data permanently removes time entries, absences, and settings stored by this app. This cannot be undone." : "Sletting av dataene dine fjerner permanent tidsregistreringer, fravær og innstillinger lagret av denne appen. Dette kan ikke angres.",
		"Delivery" : "Levering",
		"Departure time zone" : "Tidssone for avreise",
		"Describe how you travelled. Add a block for each part — for example outbound drive, flight, return trip." : "Beskriv hvordan du reiste. Legg til en etappe for hver del — for eksempel utreise med bil, fly, hjemreise.",
		"Describe what was wrong and why the times should change." : "Beskriv hva som var galt, og hvorfor tidene bør endres.",
