		"Dieses Bundesland wird automatisch verwendet, wenn für Mitarbeitende oder Teams kein eigenes Bundesland gesetzt ist." : "Denne delstaten brukes automatisk hvis det ikke er angitt en egen delstat for medarbeidere eller team.",
		"Different rules for travel days (advanced)" : "Andre regler for reisedager (avansert)",
