		"Do these three steps before anyone records time. Until then, holidays, target hours, and break rules are not reliable." : "Gjør disse tre trinnene før noen registrerer tid. Frem til da er ikke ferier, kontraktsmål og pauseregler pålitelige.",
		"Do you really want to cancel this absence? This cannot be undone." : "Vil virkelig avbryte dette fraværet? Dette kan ikke angres.",
		"Do you really want to remove the holiday \"{name}\" on {date}?" : "Vil virkelig fjerne helligdagen «{name}» den {date}?",
