		"Download" : "Last ned",
		"Download CSV" : "Last ned CSV",
		"Download PDF" : "Last ned PDF",
		"Download a DATEV text file for the same start and end dates as above. Hour premiums appear as extra Lohnart lines only when mapped in Global settings." : "Last ned en DATEV-tekstfil for samme start- og sluttdato som ovenfor. Timetillegg vises som ekstra Lohnart-linjer bare når de er kartlagt i Globale innstillinger.",
		"Download balance PDF" : "Last ned saldo-PDF",
		"Download for each person" : "Last ned for hver person",
		"Download my DATEV file" : "Last ned DATEV-filen min",
		"Download organisation DATEV file" : "Last ned organisasjonens DATEV-fil",
		"Download revision PDF" : "Last ned revisjons-PDF",
		"Download revision PDF for {name}" : "Last ned revisjons-PDF for {name}",
		"Download revision-safe monthly PDFs for team members (same document as employees)." : "Last ned revisjonssikre månedlige PDF'er til teammedlemmer (samme dokument som medarbeidere).",
		"Download revision-safe monthly certificate PDF for {period}" : "Last ned revisjonssikkert månedlig sertifikat-PDF for {period}",
		"Download revision-secure month PDFs for team members (same document as the employee)." : "Last ned revisjonssikre måneds PDF'er for teammedlemmer (samme dokument som medarbeideren).",
		"Download team absences by type as CSV" : "Last ned teamets fravær etter type som CSV",
		"Download team overtime overview as CSV" : "Last ned holdovertidsoversikt som CSV",
		"Download team overtime with monthly balances as CSV" : "Last ned teamets overtid med månedlige saldoer som CSV",
		"Download the activity log as a file" : "Last ned aktivitetsloggen som en fil",
		"Download the same revision-secure month PDF that the employee receives. The cryptographic snapshot and hash match the sealed record." : "Last ned den samme revisjonssikre måneds-PDF, som medarbeideren mottar. Det kryptografiske øyeblikksbilde og hash matcher den forseglede post.",
		"Download your time entries as a CSV file" : "Last ned timeregistreringene dine som en CSV-fil",
		"Download your time entries as a PDF file" : "Last ned tidsregistreringene dine som PDF-fil",
		"Download your time entries as a file" : "Last ned tidsregistreringene som en fil",
		"Downloads the currently filtered list as a PDF. Without a filter, the last 30 days are exported." : "Laster ned den filtrerte listen som PDF. Uten filter eksporteres de siste 30 dagene.",
		"Downloads the last 30 days as CSV (long layout): each row shows start and end times; overnight shifts appear as two rows when your administrator enables midnight split. Use Reports for date range and optional wide layout." : "Laster ned de siste 30 dagene som CSV (langt oppsett): hver rad viser start- og sluttider; nattevakter vises som to rader når administratoren din aktiverer midnattsdeling. Bruk Rapporter for datoperiode og valgfritt bredt oppsett.",
		"Draft" : "Kladde",
		"Draft — not yet submitted" : "Utkast — ennå ikke sendt inn",
		"Draft → Activate when ready → Retire when superseded. Only drafts can be edited or deleted." : "Utkast → Aktiver når klar → Ta ut av bruk når den erstattes. Bare utkast kan redigeres eller slettes.",
		"Driving" : "Kjøring",
		"Driving time is legally free (not working time by law)" : "Kjøretid er juridisk fri (ikke arbeidstid i lovens forstand)",
		"Driving time plus work done" : "Kjøretid pluss utført arbeid",
		"Duration" : "Varighet",
		"Duration cannot exceed %d days" : "Varigheten kan ikke overstige %d dager.",
		"Duration cannot exceed 365 days" : "Varighet kan ikke overstige 365 dager",
		"E-Mail" : "E-post",
		"Each break must be at least %d minutes." : "Hver pause må være minst %d minutter.",
		"Each break must be at least 15 minutes and within working hours." : "Hver pause må være minst 15 minutter og innenfor arbeidstiden.",
		"Each break must be at least 15 minutes." : "Hver pause må være minst 15 minutter.",
		"Each break must be at least {minutes} minutes." : "Hver pause må være minst {minutes} minutter.",
		"Each break must have both a start and end time, or leave the row empty." : "Hver pause skal ha både et start- og sluttidspunkt, eller lad rekken stå tom.",
		"Each bulk item must be an object with type and id." : "Hvert masseelement må være et objekt med type og id.",
		"Each card below is one topic. Use the links above to jump, then save at the bottom." : "Hvert kort nedenfor er ett tema. Bruk lenkene ovenfor for å hoppe, og lagre deretter nederst.",
		"Each event title shows the employee name and absence type (for example “Alex – Vacation”). After changing language or scope, generate a new link and update your calendar subscription." : "Hver hendelsestittel viser navn og fraværstype (f.eks. « Alex (Ferie) »). Etter endring av språk eller omfang: opprett ny lenke og oppdater abonnementet.",
		"Each presence time needs a day, a start and an end." : "Hver fremmøtetid trenger en dag, en start og en slutt.",
		"Each refresh covers approved absences from the last 3 months through the next 12 months. Subscribe once — the window moves forward automatically." : "Hver oppdatering dekker godkjente fravær fra siste 3 måneder til neste 12. Abonner én gang — vinduet flyttes automatisk.",
		"Each refresh includes approved absences from the last 3 months through the next 12 months. The window moves forward automatically — subscribe once." : "Hver oppdatering inkluderer godkjente fravær fra de siste 3 månedene til de neste 12 månedene. Vinduet flyttes automatisk frem — abonner én gang.",
		"Each row is one recorded change. Newest entries appear first." : "Hver rad er én registrert endring. Nyeste oppføringer vises først.",
		"Each rule set decides how much of a business trip counts for the time account. Active versions are frozen — changes create a new draft version." : "Hvert regelsett avgjør hvor mye av en forretningsreise som teller på tidskontoen. Aktive versjoner er fryst — endringer lager en ny utkastversjon.",
		"Each scope (All employees or one team) can have one active link. Generating or rotating replaces the previous URL immediately — calendar apps using the old link stop updating." : "Hvert omfang (alle ansatte eller ett team) kan bare ha én aktiv lenke. Generering eller rotasjon erstatter forrige URL umiddelbart — kalenderapper med den gamle lenken oppdateres ikke lenger.",
		"Each scope and calendar language has its own link. Links are stored encrypted on this server so you can copy them again later. Rotating a link invalidates the previous URL immediately." : "Hvert omfang og kalenderspråk har sin egen lenke. Lenker lagres kryptert på denne serveren slik at de kan kopieres igjen senere. Bytte av lenke ugyldiggjør den forrige URL-en med en gang.",
		"Each trip day is measured by" : "Hver reisedag måles etter",
		"Each work day needs a start and an end that is later than the start." : "Hver arbeidsdag trenger en start og en slutt som er senere enn starten.",
		"Easter Monday" : "2. påskedag",
