		"Employees add completed work blocks by date and time. The punch clock is hidden for everyone." : "Medarbeidere legger til avsluttet arbeidsblokker etter dato og tidspunkt. Stempeluret er skjult for alle.",
		"Employees and work schedules" : "Medarbeidere og arbeidsplaner",
		"Employees can accumulate overtime up to a maximum (bank). Hours above the cap can be paid out at month end via Admin → Overtime payouts." : "Ansatte kan oppspare overtid opp til et maksimum (konto). Timer over taket kan utbetales ved månedsslutt via Admin → Overtidsutbetalinger.",
		"Employees can clock in\/out on the dashboard and add manual time entries." : "Medarbeidere kan stemple inn\/ut på dashboardet og legge til manuelle tidsregistreringer.",
		"Employees can link time to customer projects." : "Medarbeidere kan koble tid til kundeprosjekter.",
		"Employees must use the punch clock. Manual time entries are hidden for everyone." : "Medarbeidere må bruke stempelklokken. Manuelle tidsregistreringer er skjult for alle.",
		"Employees seal a calendar month when work is complete. Administrators can reopen a sealed month if corrections are needed." : "Medarbeidere forsegler en kalendermåned, når arbeidet er avsluttet. Administratorer kan gjenåpne en lukket måned, hvis det er behov for korreksjon.",
		"Employees see these types next to the built-in ones when they request an absence. Deleting a type that is still in use only disables it, so existing records keep working." : "Ansatte ser disse typene ved siden av de innebygde når de ber om fravær. Å slette en type som fortsatt er i bruk deaktiverer den bare, slik at eksisterende registreringer fortsatt fungerer.",
		"Employees who reached overtime or undertime thresholds, or whose overtime bank needs attention." : "Medarbeidere som har nådd over- eller undertidsterskler, eller hvis overtidsbank har behov for oppmerksomhet.",
		"Employees with another language see the translation below; everyone else sees the name above." : "Ansatte med et annet språk ser oversettelsen nedenfor; alle andre ser navnet ovenfor.",
