		"Enter a four-digit year (e.g. 2026)." : "Skriv inn et firesifret årstal (f.eks. 2026).",
		"Enter a hours delta (e.g. -10 or 5)." : "Angi et timedifferanse (f.eks. -10 eller 5).",
		"Enter a name for this work schedule (e.g., \"Full-Time\", \"Part-Time\")" : "Skriv inn et navn til denne arbeidsplan (f.eks. \"Heltid\", \"Deltid\")",
		"Enter a number between 0 and 366 with up to two decimal places (for example 25, 25.5, 27.75, or 31.2). Comma or dot both work." : "Skriv inn et tall mellom 0 og 366 med opptil to desimaler (f.eks. 25, 25,5, 27,75 eller 31,2). Komma eller punktum fungerer begge deler.",
		"Enter a terminal label" : "Angi en terminalbetegnelse",
		"Enter a unit count and minutes per unit (e.g. 27 and 45)." : "Oppgi et enhetsantall og minutter per enhet (f.eks. 27 og 45).",
		"Enter a user id." : "Skriv inn en bruker-ID.",
		"Enter a valid date range." : "Skriv inn et gyldig datointervall.",
		"Enter a valid number of vacation days." : "Skriv inn et gyldig antall feriedager.",
		"Enter a value between 0 and 366 days." : "Skriv inn en verdi mellom 0 og 366 dager.",
		"Enter absence minutes between 0 and 1440." : "Skriv inn fraværminutter mellom 0 og 1440.",
		"Enter annual vacation in days — the same numbers you already know (e.g. 25). Booking and remaining balances use hours; we convert using your hours-per-day factor. A higher layer always wins." : "Angi årlig ferie i dager — de samme tallene kjenner (f.eks. 25). Bestilling og gjenværende saldoer bruker timer; vi konverterer med din timer-per-dag-faktor. Et høyere lag vinner alltid.",
		"Enter annual vacation in days — the same numbers you already know (e.g. 25). Booking and remaining balances use hours; we convert using your hours-per-day factor. Rules are evaluated top-down: a higher layer always wins." : "Skriv inn årlig ferie i dager — de samme tallene du allerede kjenner (f.eks. 25). Booking og restsaldoer bruker timer; vi konverterer med din timer-per-dag-faktor. Regler vurderes ovenfra og ned: et høyere lag vinner alltid.",
		"Enter both break start and break end, or leave both empty." : "Angi både pausens start og slutt, eller la begge stå tomme.",
		"Enter days as usual (e.g. 25). We convert to hours automatically — no calculator needed." : "Skriv inn dager som vanlig (f.eks. 25). Vi regner automatisk om til timer — ingen kalkulator nødvendig.",
		"Enter reason for declining..." : "Angi begrunnelse til avvisning...",
		"Enter reason for rejection..." : "Angi begrunnelse til avvisning...",
		"Enter the annual vacation days (e.g. 30 or 24.5)." : "Skriv inn de årlige feriedager (f.eks. 30 eller 24.5).",
		"Enter the date and times as they should be recorded." : "Skriv inn dato og tidspunkt, som de skal registreres.",
		"Enter the weekly units and minutes per unit — the weekly hours above are filled in automatically." : "Oppgi ukens enheter og minutter per enhet — uketimene ovenfor fylles ut automatisk.",
		"Enter this code on the tablet within 10 minutes. It is shown only once." : "Skriv inn denne koden på nettbrettet innen 10 minutter. Den vises bare én gang.",
		"Enter vacation days as usual (e.g. 25). We convert to hours automatically using %s hours per day — no calculator needed." : "Skriv inn feriedager som vanlig (f.eks. 25). Vi konverterer automatisk til timer med %s timer per dag — ingen kalkulator nødvendig.",
		"Enter your working times including breaks. The system will automatically check compliance with German labor law (ArbZG)." : "Skriv inn dine arbeidstider inklusive pauser. Systemet vil automatisk kontrollere etterlevelse av tysk arbeidslovgivning (ArbZG).",
