		"Everyone listed has a finalized month for your selection and matches your permissions." : "Alle på listen har en fullført måned for valget ditt og samsvarer med tillatelsene dine.",
		"Everyone matching your search is already assigned to this unit." : "Alle som samsvarer med søket ditt, er allerede tildelt denne enheten.",
		"Everyone who already has a badge or PIN. Use the row buttons to create a new PIN or remove credentials." : "Alle som allerede har et badge eller en PIN. Bruk radknappene for å opprette en ny PIN eller fjerne påloggingsinfo.",
		"Everyone with a Nextcloud account is listed. Use search to find someone quickly." : "Alle med en Nextcloud-konto er listet. Bruk søk for raskt å finne noen.",
		"Everything looks good!" : "Alt ser godt ud!",
		"Exact days" : "Eksakte dager",
		"Example for CSV\/JSON long layout: row 1 has date = first calendar day, start_time 22:00:00, end_time 23:59:59; row 2 has date = next day, start_time 00:00:00, end_time 06:00:00. Column working_hours is the work time share per segment (the segments sum to the full entry). This is not an extra \"break\" row — rest breaks remain tied to the original booking; split rows may show empty break columns." : "Eksempel på CSV\/JSON langt oppsett: rad 1 har dato = første kalenderdag, starttid 22:00:00, sluttid 23:59:59; rad 2 har dato = neste dag, starttid 00:00:00, sluttid 06:00:00. Kolonnen working_hours er arbeidstidsandelen per segment (segmentene summerer til hele registreringen). Dette er ikke en ekstra «pause»-rad – hvilepauser forblir knyttet til den opprinnelige registreringen; delte rader kan ha tomme pausekolonner.",
		"Example: 30 or 24.5 days per year" : "Eksempel: 30 eller 24,5 dager om året",
		"Example: Sunday 2 h → 2.0 h @ 100%%" : "Eksempel: søndag 2 t → 2,0 t @ 100%%",
		"Example: Sunday 2 h → 2.0 h @ __PCT__%%" : "Eksempel: søndag 2 t → 2,0 t @ __PCT__%%",
		"Example: hire 1 July + 3 months → usable until 30 September." : "Eksempel: ansettelse 1. juli + 3 måneder → brukbar til 30. september.",
		"Example: tier 2:00 plus 8:00 actual work books 10:00." : "Eksempel: trinn 2:00 pluss 8:00 faktisk arbeid bokfører 10:00.",
		"Example: tier 9:00 always books 9:00, no matter the actual work." : "Eksempel: trinn 9:00 bokfører alltid 9:00, uansett det faktiske arbeidet.",
		"Example: tier 9:00 with 10:00 actual work books only 9:00." : "Eksempel: trinn 9:00 med 10:00 faktisk arbeid bokfører bare 9:00.",
		"Example: tier 9:00 with 7:00 actual work books 9:00 — a 2:00 top-up." : "Eksempel: trinn 9:00 med 7:00 faktisk arbeid bokfører 9:00 — et tillegg på 2:00.",
		"Example: turn on Sunday to see a sample." : "Eksempel: slå på søndag for å se et eksempel.",
		"Excel File (XLSX)" : "Excel-fil (XLSX)",
