		"Finalize a full calendar month after it has ended, when your times are complete. The app stores a cryptographic snapshot and a PDF you can archive." : "Fullfør en hel kalendermåned etter at den er avsluttet, når timene dine er komplette. Appen lagrer et kryptografisk øyeblikksbilde og en PDF Du kan arkivere.",
