		"Find ProjectCheck in Nextcloud Apps and click Enable. Then return here and turn on the connection." : "Finn ProjectCheck i Nextcloud-apper og klikk Aktiver. Kom deretter tilbake hit og slå på tilkoblingen.",
		"Find a person" : "Finn en person",
