		"Finish the paused session on the dashboard, or contact your administrator." : "Avslutt den pausede økten på dashbordet, eller kontakt administratoren din.",
		"Finish tour" : "Avslutt omvisningen",
		"First" : "Først",
		"First choose a sealed month, then download the official revision PDF for each person in your scope." : "Velg først en forseglet måned, og last deretter ned den offisielle revisjons-PDF-en for hver person i omfanget ditt.",
		"First choose the scope above, then pick the type of report." : "Velg først omfanget ovenfor, og velg deretter rapporttypen.",
		"First day" : "Første dag",
		"First day away" : "Første dag borte",
		"First day of employment. Vacation for the year of hire is prorated from this date." : "Første ansettelsesdag. Ferie for ansettelsesåret beregnes pro-rata fra denne datoen.",
		"First pick the country whose working time law applies, then the default region for public holidays." : "Velg først landet hvis arbeidstidslov gjelder, og deretter standardregionen for helligdager.",
		"Fixed value per person" : "Fast verdi per person",
		"Fixed — always exactly this amount" : "Fast — alltid nøyaktig dette beløpet",
		"Fixed?" : "Fast?",
		"Flex policy quiet window end hour" : "Flex-policy stille vindu slutt-tidspunkt",
		"Flex policy quiet window start hour" : "Flex-policy stille vindu start-tidspunkt",
		"Flexible" : "Fleksibel",
		"For a 38.5-hour week, use 7.7 hours per day (= 38.5 ÷ 5) so open day balances convert fairly. The default 8 under-converts those balances." : "For en 38,5-timersuke bruk 7,7 timer\/dag (= 38,5 ÷ 5) slik at åpne dagssaldoer konverteres rettferdig. Standard 8 underkonverterer.",
		"For approved absences, an email with an iCal attachment (.ics) can be sent automatically." : "For godkjente fravær kan en e-post med et iCal-vedlegg (.ics) sendes automatisk.",
		"For clocked entries less than %d days old: use Edit to change times, or Delete to remove the entry entirely. Older clocked entries: use Request correction. Entries in a finalized month or approved by your manager cannot be deleted here." : "For stemplede registreringer yngre enn %d dager: bruk Rediger for å endre tider, eller Slett for å fjerne registreringen helt. Eldre stemplede registreringer: Be om korrigering. Registreringer i en avsluttet måned eller godkjent av lederen din kan ikke slettes her.",
		"For non-shift models (flex policy), automatic clock-out is suppressed inside this daytime window. Shift work remains strict." : "For ikke-skiftmodeller (fleksibel policy) undertrykkes automatisk utstempling i dette dagsvinduet. Skiftarbeid forblir strengt.",
		"For organization scope, download is available for working time export after preview." : "For organisasjonsomfang er nedlasting tilgjengelig for arbeidstidseksport etter forhåndsvisning.",
		"For payroll (DATEV) files, open Administration → Global settings and use the «Exports and reporting» section with your date range. This page offers CSV and JSON only." : "For lønnsfiler (DATEV) skal du åpne Administrasjon → Globale innstillinger og bruke seksjonen «Eksporter og rapportering» med ditt datointervall. Denne siden tilbyr kun CSV og JSON.",
		"For security and performance, entries load only when you click Show with a valid date range." : "Av sikkerhets- og ytelseshensyn lastes registreringer bare inn når du klikker Vis med et gyldig datointervall.",
		"For security and performance, results are only loaded after both start and end date are set." : "Av sikkerhets- og ytelseshensyn lastes resultater bare inn etter at både start- og sluttdato er satt.",
		"For the selected absence types, a substitute must be designated." : "For de valgte fraværstypene skal det utpekes en stedfortreder.",
		"For whom?" : "For hvem?",
		"Form actions" : "Form handlinger",
		"Form initialization failed. Please refresh the page." : "Skjemainitialisering mislyktes. Oppdater siden.",
		"Format: AZC2 followed by a signed payload. One key per organisation." : "Format: AZC2 efterfulgt av en signert nyttelast. Én nøkkel per organisasjon.",
		"Format: dd.mm.yyyy" : "Format: dd.mm.åååå",
		"Formula: 30 × (work days per week ÷ 5)." : "Formel: 30 × (arbeidsdager per uke ÷ 5).",
		"Four decisions: name, amount, recipients, start date. The linked absence type is created automatically." : "Fire beslutninger: navn, beløp, mottakere, startdato. Den tilknyttede fraværstypen opprettes automatisk.",
		"Foyer kiosk terminals and employee badges" : "Foyer-kioskterminaler og ansattes badges",
