		"Free to download. Your IT assigns official mobile and terminal seats on the License page." : "Gratis å hente. IT tildeler offisielle mobil- og terminalplasser på lisenssiden.",
		"Free to run under AGPL" : "Gratis å kjøre under AGPL",
