		"Full day" : "Hel dag",
		"Full day or half day for this date. Morning or afternoon is not tracked." : "Hel eller halv dag for denne datoen. Formiddag eller ettermiddag spores ikke.",
		"Full months (Zwölftelung, German default)" : "Hele måneder (Zwölftelung, tysk standard)",
		"Full months (Zwölftelung, common DE default)" : "Hele måneder (Zwölftelung, vanlig DE-standard)",
		"Full months: each calendar month touched by the employment counts as 1\/12 of the annual entitlement; a fraction of half a day or more is rounded up to a full day (BUrlG §5). Exact days: annual entitlement times worked days divided by days in the year. This is not legal advice — consult HR for your collective agreement." : "Hele måneder: hver kalendermåned ansettelsen berører, teller som 1\/12 av den årlige retten; en brøkdel på en halv dag eller mer avrundes opp til en hel dag (BUrlG §5). Eksakte dager: årlig rett ganger arbeidede dager dividert med dager i året. Dette er ikke juridisk rådgivning — konsulter HR for tariffavtalen deres.",
		"Full range" : "Fullt intervall",
		"Full-Time" : "Heltid",
		"Full-day holiday" : "Heldagshelligdag",
		"Full-time" : "Heltid",
		"Future dates are not allowed. Please enter a date today or in the past." : "Fremtidige datoer er ikke tillatt. Skriv inn en dato i dag eller tidligere.",
		"GDPR \/ DSGVO Ready" : "GDPR-klar",
