		"Generate" : "Frembringe",
		"Generate PIN" : "Generer PIN",
		"Generate a new PIN for {name}? The previous PIN will stop working immediately." : "Generer en ny PIN for {name}? Den forrige PIN slutter å fungere umiddelbart.",
		"Generate a new link for this scope? The current subscription URL will stop working immediately." : "Generere en ny lenke for dette omfanget? Den nåværende abonnements-URL-en slutter å fungere umiddelbart.",
		"Generate a subscription link (secret like a password)." : "Opprett abonnementslenke (hemmelig som et passord).",
		"Generate and download" : "Generer og last ned",
		"Generate and download the report" : "Generer og last ned rapporten",
		"Generate and export time entries, absences, and compliance reports" : "Opprett og eksporter timeregistreringer, fravær og etterlevelsesrapporter",
		"Generate and export working time reports" : "Generer og eksporter arbeidstidsrapporter",
		"Generate and view detailed reports on working hours, overtime, and absences" : "Generer og vis detaljerte rapporter om arbeidstid, overtid og fravær",
		"Generate feed URL" : "Generer feed-URL",
		"Generate new PIN" : "Generer ny PIN-kode",
		"Generate one calendar subscription link per scope. The feed contains approved absences only and never includes free-text reasons." : "Opprett én kalenderabonnementslenke per omfang. Feeden inneholder kun godkjente fravær og aldri fritekstgrunner.",
		"Generate one calendar subscription link per team and manager scope. The feed contains approved absences only and never includes free-text reasons." : "Generer én kalenderabonnementslenke per team og lederomfang. Feeden inneholder bare godkjente fravær og aldri fritekstbegrunnelser.",
		"Generate privacy-safe calendar subscription links per team and manager scope." : "Generer personvernvennlige kalenderabonnementslenker per team og lederomfang.",
