		"Geneva" : "Genève",
		"German Labor Law (Arbeitszeitgesetz - ArbZG)" : "Tysk arbeidslov (Arbeitszeitgesetz - ArbZG)",
		"German Labor Law Compliant" : "I samsvar med tysk arbeidslov",
		"German labor law (ArbZG) allows a maximum of 10 hours per day. You have entered {hours} hours." : "Tysk arbeidsrett (ArbZG) tillater maksimalt 10 timer per dag. Du har angitt {hours} timer.",
		"German labor law (ArbZG) requires:" : "Tysk arbeidsrett (ArbZG) krever:",
		"German labor law compliance" : "Etterlevelse av tysk arbeidslovgivning",
		"German labor law compliant time tracking for Nextcloud" : "Tidsregistrering i samsvar med tysk arbeidslov for Nextcloud",
		"German labor law requires at least 30 minutes break after 6 hours of work. You have only {minutes} minutes." : "Tysk arbeidsrett krever minst 30 minutters pause etter 6 timers arbeid. Du har bare {minutes} minutter.",
		"German labor law requires at least 45 minutes break after 9 hours of work. You have only {minutes} minutes." : "Tysk arbeidsrett krever minst 45 minutters pause etter 9 timers arbeid. Du har bare {minutes} minutter.",
		"German law: 30 min break from 6 h work, 45 min from 9 h. Enable automatic breaks or add times yourself." : "Tysk lov: 30 min pause fra 6 timers arbeid, 45 min fra 9 timer. Aktiver automatiske pauser eller legg til tider selv.",
		"Germany" : "Tyskland",
		"Gesamtzahl der Mitarbeitenden mit Zugriff auf die Zeiterfassung" : "Totalt antall medarbeidere med tilgang til tidsregistrering",
		"Gesetzliche und zusätzliche Feiertage pro Bundesland verwalten. Diese Kalender werden für Urlaub, Arbeitszeitberechnung und Compliance-Prüfungen genutzt." : "Administrer lovpålagte og ytterligere helligdager per delstat. Disse kalenderne brukes til ferie, arbeidstidsberegning og etterlevelseskontroll.",
		"Get Started" : "Kom i gang",
		"Get a notification when it's time to take a required break. For example, after 5.5 hours you'll get a reminder to take at least a 15-minute break (ArG)." : "Få et varsel når det er tid for en påkrevd pause. For eksempel får etter 5,5 timer en påminnelse om minst 15 minutters pause (ArG).",
		"Get a notification when it's time to take a required break. For example, after more than 6 hours you'll get a reminder to take at least a 30-minute break (AZG)." : "Få et varsel når det er tid for en påkrevd pause. For eksempel får etter mer enn 6 timer en påminnelse om minst 30 minutters pause (AZG).",
		"Get a notification when it's time to take a required break. For example, if you work more than 6 hours, you'll get a reminder to take at least a 30-minute break." : "Få et varsel når det er tid for å ta en påkrevd pause. Hvis du for eksempel jobber mer enn 6 timer, får du en påminnelse om å ta en pause på minst 30 minutter.",
		"Get the App" : "Hent appen",
