		"Half-day vacation is only allowed when start and end are the same day. For mixed half and full days, submit separate requests." : "Halvdagsferie er bare tillatt når start og slutt er samme dag. For blandede halv- og heldager, send separate forespørsler.",
		"Half-day vacation request submitted successfully" : "Forespørsel om halv feriedag er sendt inn",
