		"Hello %s," : "Hei %s,",
		"Hello{nameSuffix},\n\nYour kiosk PIN for ArbeitszeitCheck is: {pin}\n\nKeep this PIN private. You can change it only by asking an administrator to generate a new one.\n" : "Hei{nameSuffix}, Kiosk-PIN-en din for ArbeitszeitCheck er: {pin} Hold denne PIN-en privat. Du kan bare endre den ved å be en administrator om å generere en ny.",
