		"Help: These skip links let you jump directly to the main content or to the app navigation." : "Hjelp: Disse hurtigkoblinger lar deg hoppe direkte til hovedinnholdet eller til appnavigeringen.",
		"Here under “Badges & PIN”: allow access, generate PINs, or start “Scan badge at tablet” (the chip UID is read automatically — you never look it up)." : "Her under \"Badges & PIN\": tillat tilgang, generer PIN-er, eller start \"Skann badge ved nettbrett\" (chip-UID leses automatisk — slår det aldri opp).",
		"Here you define additional leave entitlements and their quotas." : "Her definerer du ytterligere permisjonsrettigheter og deres kvoter.",
