		"Minimum %1$d-hour rest period required between shifts (%2$s). Your last shift ended on %3$s at %4$s. You can clock in after %5$s (in %6$.1f hours)." : "Minst %1$d timers hviletid kreves mellom skift (%2$s). Det siste skiftet ditt sluttet %3$s kl. %4$s. Du kan stemple inn etter %5$s (om %6$.1f timer).",
		"Minimum %1$d-hour rest period required between shifts (%2$s). Your last shift ended on %3$s at %4$s. You can clock in after %5$s (in %6$.1f hours). For a short break in the same session, use Pause instead of clocking out. Morning and afternoon blocks on the same calendar day (split shift) are allowed when the previous block did not run overnight." : "Minst %1$d timers hvileperiode kreves mellom vakter (%2$s). Din siste vakt sluttet %3$s kl. %4$s. Du kan stemple inn etter %5$s (om %6$.1f timer). For en kort pause i samme økt, bruk Pause i stedet for å stemple ut. Formiddags- og ettermiddagsblokker samme kalenderdag (delt vakt) er tillatt når forrige blokk ikke gikk over midnatt.",
		"Minimum %1$d-hour rest period required between shifts (ArbZG §5). Your last shift ended at %2$s. You can clock in after %3$s (in %4$.1f hours)." : "Minst %1$d timers hviletid kreves mellom skift (ArbZG §5). Det siste skiftet ditt sluttet kl. %2$s. Du kan stemple inn etter %3$s (om %4$.1f timer).",
		"Minimum %1$d-hour rest period required between shifts (ArbZG §5). Your last shift ended on %2$s at %3$s. This entry cannot start before %4$s (%5$.1f hours required)." : "Minst %1$d timers hviletid påkrevd mellom skift (ArbZG §5). Ditt siste skift sluttet den %2$s kl. %3$s. Denne posten kan ikke starte før %4$s (%5$.1f timer påkrevd).",
