		"Open Administration, then %1$sEmployees%2$s, and open the person. Under Work schedule, choose that model. Repeat for everyone who records time, including yourself." : "Åpne Administrasjon og deretter %1$sMedarbeidere%2$s og åpne personen. Under Arbeidsplan velger du den modellen. Gjenta for alle som registrerer tid, inkludert deg selv.",
		"Open Administration, then %1$sHolidays and calendars%2$s. Choose the country and the default region for public holidays, then check the calendar for this year." : "Åpne Administrasjon og deretter %1$sHelligdager og kalendere%2$s. Velg land og standardregion for offentlige helligdager, og kontroller deretter kalenderen for i år.",
		"Open Administration, then %1$sWorking time models%2$s. Create at least one schedule, for example full-time or part-time." : "Åpne Administrasjon og deretter %1$sArbeidstidsmodeller%2$s. Opprett minst én plan, for eksempel heltid eller deltid.",
