		"Open shows ArbeitszeitCheck in the menu for everyone. Restricted hides it unless the person is allow-listed. System and delegated app administrators always pass the door. Employee and manager roles still apply after the door." : "Åpen viser ArbeitszeitCheck i menyen for alle. Begrenset skjuler den med mindre personen er på tillatelseslisten. System- og delegerte appadministratorer slipper alltid gjennom. Ansatt- og lederroller gjelder fortsatt etter døren.",
