		"Pick a date range, then Show. Leave employee empty for your whole team, or search and select one person. Maximum range: %d days." : "Velg et datointervall, og klikk deretter Vis. La «Ansatt»-feltet stå tomt for hele teamet ditt, eller søk og velg én person. Maksimalt intervall: %d dager.",
