		"ProjectCheck is connected, but you have no projects to choose from right now. You can still save your time without a project, or review your connection in Settings." : "ProjectCheck er tilkoblet, men du har ingen prosjekter å velge mellom akkurat nå. Du kan fortsatt lagre tiden uten et prosjekt, eller gjennomgå tilkoblingen i Innstillinger.",
		"ProjectCheck is enabled, but you have no customer projects to choose from. Ask your project manager to add you to a project team, or clock in without a project." : "ProjectCheck er aktivert, men du har ingen kundeprosjekter å velge mellom. Be prosjektlederen din om å legge deg til i et prosjektteam, eller stemple inn uten prosjekt.",
		"ProjectCheck is installed on this server. When the connection is on, you can link your working hours to a customer project — directly when you clock in and on manual time entries. This helps bill the right project. When it is off, no project picker is shown and your hours stay private to ArbeitszeitCheck." : "ProjectCheck er installert på denne serveren. Når koblingen er slått på, kan du knytte arbeidstiden din til et kundeprosjekt — direkte når du stempler inn og ved manuelle tidsregistreringer. Det hjelper med å fakturere riktig prosjekt. Når den er slått av, vises ingen prosjektvelger, og timene dine forblir private i ArbeitszeitCheck.",
		"ProjectCheck is limited to some groups" : "ProjectCheck er begrenset til noen grupper",
		"ProjectCheck linking is turned off" : "ProjectCheck-kobling er slått av",
