		"Saved with “Save all settings” below. Existing links on old time entries stay as they are; turning this off only stops new links and hides the project picker. Projects with per-person pricing still appear only for users on the project team." : "Lagres med «Lagre alle innstillinger» nedenfor. Eksisterende koblinger på gamle registreringer forblir som de er; å slå dette av stopper bare nye koblinger og skjuler prosjektvelgeren. Prosjekter med pris per person vises fortsatt bare for brukere i prosjektteamet.",
