		"Security note: the URL is scoped to the selected team and manager, stores only a token hash on the server, and is invalidated immediately when you rotate it." : "Sikkerhetsmerknad: URL-en er begrenset til valgt team og leder, lagrer bare en token-hash på serveren og ugyldiggjøres umiddelbart når du fornyer den.",
		"Security note: the URL is scoped to your selection, stores only a token hash on the server, and is invalidated immediately when you rotate it." : "Sikkerhetsmerknad: URL-en er begrenset til Deres valg, lagrer bare en token-hash på serveren og ugyldiggjøres umiddelbart ved fornyelse.",
		"Security: links are encrypted at rest on this server (app admins can view them here). Anyone with the full URL can read that scoped feed until you rotate the link." : "Sikkerhet: lenker lagres kryptert på denne serveren (app-administratorer kan se dem her). Alle med den fullstendige URL-en kan lese denne feeden til lenken byttes.",
