		"Teams, Abteilungen oder andere Organisationseinheiten in einer flexiblen Hierarchie definieren. Mitglieder und Leitungen zuweisen. Wenn unten aktiviert, können Leitungen Abwesenheiten und Zeitkorrekturen ihrer Einheiten freigeben." : "Definer team, avdelinger eller andre organisatoriske enheter i et fleksibelt hierarki. Tildel medlemmer og ledere. Hvis det er aktivert nedenfor, kan ledere godkjenne fravær og tidskorrigeringer for enhetene sine.",
		"Technical code for reports and integrations. Lowercase letters, numbers and underscores. Leave empty to generate it from the name." : "Teknisk kode for rapporter og integrasjoner. Små bokstaver, tall og understreker. La stå tomt for å generere den fra navnet.",
