		"This widget is only available for app administrators." : "Denne widgeten er kun tilgjengelig for app-administratorer.",
		"This will be saved immediately as approved and shown with the \"Past record\" badge in calendars, timelines and reports. Audit trail captures who recorded it." : "Dette lagres umiddelbart som godkjent og vises med merket \"Tidligere post\" i kalendere, tidslinjer og rapporter. Revisjonssporet registrerer hvem som registrerte det.",
		"This work location is no longer active." : "Dette arbeidsstedet er ikke lenger aktivt.",
		"This work location is still referenced and cannot be removed." : "Dette arbeidsstedet er fortsatt referert og kan ikke fjernes.",
		"This work location still has active default policies. End them first." : "Dette arbeidsstedet har fortsatt aktive standardpolicyer. Avslutt dem først.",
		"This working time follows the configured labour-law rules." : "Denne arbeidstiden følger de konfigurerte arbeidsrettsreglene.",
		"This year" : "I år",
		"Three simple steps: find the employee, allow kiosk access, then assign a badge or PIN." : "Tre enkle steg: finn den ansatte, tillat kiosktilgang, og tildel deretter et badge eller en PIN.",
		"Threshold values must be valid numbers." : "Terskelverdier må være gyldige tall.",
		"Thu" : "Tor",
		"Thunderbird: Calendar → New calendar → On the network → paste the webcal link. Delete an old subscription before adding a changed link." : "Thunderbird: Kalender → Ny kalender → På nettverket → lim inn webcal-lenken. Slett gammelt abonnement før endret lenke.",
