		"Times currently saved for this entry" : "Tider som er lagret for denne posten akkurat nå",
		"Times when people on this schedule must be working or on approved leave — e.g. lessons or consultation hours. Days without an entry are never flagged. Leave empty if not needed." : "Tider når personer på dette skjemaet må jobbe eller ha godkjent permisjon — f.eks. undervisningstimer eller konsultasjonstider. Dager uten oppføring flagges aldri. La stå tomt om ikke nødvendig.",
