		"Tirol" : "Kanton Tirol",
		"To" : "Til",
		"To change start or end times, use Edit. Delete removes the entire entry permanently." : "For å endre start- eller sluttid, bruk Rediger. Slett fjerner hele registreringen permanent.",
		"To change tablet settings later: press and hold the large title at the top of the home screen for 5 seconds, then enter the admin PIN. There is no public Setup button." : "For å endre nettbrettinnstillingene senere: hold nede den store tittelen øverst på startskjermen i 5 sekunder, og skriv deretter inn admin-PIN. Det finnes ingen offentlig Oppsett-knapp.",
		"To date" : "Til dato",
		"To subscribe in Nextcloud Calendar on this server, ask a Nextcloud server administrator to open this page and click “Allow Nextcloud Calendar subscriptions on this server”. Thunderbird and Outlook work without that step." : "For abonnement i Nextcloud Calendar på denne serveren: be en Nextcloud-administrator åpne siden og klikke « Tillat Nextcloud Calendar-abonnementer på denne serveren ». Thunderbird og Outlook fungerer uten dette trinnet.",
