		"Total time entries: {count}" : "Totalt antall tidsregistreringer: {count}",
		"Total vacation hours for the whole request (not per day). Full range uses the employee’s work model (schedule), not a fixed 8 hours." : "Totale ferietimer for hele forespørselen (ikke per dag). Hele intervallet bruker den ansattes arbeidsmodell (plan), ikke faste 8 timer.",
		"Total vacation hours for the whole request (not per day). “Full range” and “1 full day” use your work model (e.g. shorter Friday), not a fixed 8 hours. Public holidays reduce the final debit." : "Totale ferietimer for hele forespørselen (ikke per dag). \"Fullt intervall\" og \"1 hel dag\" bruker arbeidsmodellen din (f.eks. kortere fredag), ikke faste 8 timer. Helligdager reduserer det endelige trekket.",
		"Total: %1$d, Working: %2$d, Break: %3$d, Paused: %4$d, Clocked out: %5$d" : "Totalt: %1$d, Jobber: %2$d, Pause: %3$d, Pauset: %4$d, Stemplet ut: %5$d",
