		"Trips waiting for your review. Open one to see the recorded times, the rule result, and what will be booked." : "Reiser som venter på din gjennomgang. Åpne en for å se de registrerte tidene, regelresultatet og hva som vil bli bokført.",
		"Trust-Based" : "Tillitsbasert",
		"Trust-based" : "Tillitsbasert",
		"Try a wider date range or a different status, or clear the filter to see all entries again." : "Prøv et bredere datoområde eller en annen status, eller fjern filteret for å se alle oppføringene igjen.",
		"Try a wider date range, another work location, or a different status, or clear the filter to see all entries again." : "Prøv et bredere datoområde, et annet arbeidssted eller en annen status, eller fjern filteret for å se alle oppføringene igjen.",
		"Try again" : "Prøv igjen",
		"Try out: how many vacation days does an employee actually get on a given date? See exactly which layer was applied and why." : "Prøv: hvor mange feriedager får en medarbeider egentlig på en gitt dato? Se nøyaktig hvilket lag som ble brukt og hvorfor.",
		"Try out: how many vacation hours does an employee actually get on a given date? See exactly which layer was applied and why." : "Prøv: hvor mange ferietimer får en ansatt faktisk på en gitt dato? Se nøyaktig hvilket lag som ble brukt og hvorfor.",
		"Tue" : "Tir",
		"Tuesday" : "tirsdag",
		"Turn foyer tablet clocking on or off. Needs a Terminal license and at least one paired tablet." : "Slå foyer-nettbrett-stempling på eller av. Krever en terminallisens og minst ett paret nettbrett.",
		"Turn off manual entries if everyone must use the punch clock only." : "Slå av manuelle registreringer hvis alle kun skal bruke stempelklokken.",
		"Turn off only if you want to enter every break manually." : "Slå av kun hvis du vil skrive inn hver pause manuelt.",
		"Turn off stamping if your organisation records hours only via manual entries — the punch clock disappears for all employees." : "Slå av stempling hvis organisasjonen din kun registrerer timer via manuelle registreringer – stempelklokken forsvinner for alle medarbeidere.",
		"Turn on hour premiums" : "Aktiver timetillegg",
		"Turn on “Allow kiosk access” for this person, then continue with step 3." : "Slå på \"Tillat kiosktilgang\" for denne personen, og fortsett deretter med steg 3.",
		"Turning this off hides the project picker everywhere and stops you from linking new hours to a project. Projects you already linked stay linked until a manager changes them. Projects with per-person pricing only appear if you are on the project team." : "Hvis du slår dette av, skjules prosjektvelgeren overalt og hindrer deg i å knytte nye timer til et prosjekt. Prosjekter du allerede har knyttet, forblir knyttet til en leder endrer dem. Prosjekter med pris per person vises kun hvis du er i prosjektteamet.",
		"Type" : "Type (post)",
		"Type %s to confirm" : "Skriv inn %s for å bekrefte",
		"Type a name or email address to find employees quickly" : "Skriv inn et navn eller en e-postadresse for raskt å finne medarbeidere",
		"Type an employee name to find employees quickly" : "Skriv inn et medarbeidernavn for raskt å finne medarbeidere",
		"Type and status" : "Type og status",
		"Type at least 2 characters to search for a person." : "Skriv minst 2 tegn for å søke etter en person.",
		"Type at least 2 characters to search managers for the selected team." : "Skriv minst 2 tegn for å søke etter ledere for valgt team.",
		"Type at least 2 characters to search." : "Skriv minst 2 tegn for å søke.",
		"Type at least 2 characters to search. Leave empty to browse the list page by page." : "Skriv minst 2 tegn for å søke. La stå tomt for å bla gjennom listen side for side.",
		"Type at least 2 characters, then choose an employee. Leave empty to include everyone in your scope." : "Skriv minst 2 tegn, og velg deretter en ansatt. La stå tomt for å inkludere alle i ditt område.",
		"Type at least 2 characters, then choose the employee." : "Skriv minst 2 tegn, og velg deretter den ansatte.",
		"Type at least 2 characters, then select the employee whose finalized month you are reopening." : "Skriv minst 2 tegn, og velg deretter den ansatte hvis finaliserte måned gjenåpner.",
		"Type at least 2 characters. Leave empty to browse page by page." : "Skriv minst 2 tegn. La stå tomt for å bla side for side.",
		"Type at least 2 letters of the name or login, then pick the person from the list." : "Skriv minst 2 bokstaver av navnet eller innloggingen, og velg deretter personen fra listen.",
		"Type at least 2 letters of the name or user ID, then pick the person from the list." : "Skriv minst 2 bokstaver av navnet eller bruker-ID, og velg deretter personen fra listen.",
		"Type at least two characters, then select a person from the list." : "Skriv inn minst to tegn, og velg deretter en person fra listen.",
		"Type at least two characters, tick several people, then assign them together." : "Skriv minst to tegn, huk av flere personer, og tildel dem sammen.",
		"Type the hour and minute, or open the clock to pick a time. Example: 09:00." : "Skriv inn time og minutt, eller åpne klokken for å velge et tidspunkt. Eksempel: 09:00.",
		"Type to filter, then pick the employee whose finalized month you are reopening (their account)." : "Skriv for å filtrere, og velg deretter medarbeideren hvis avsluttede måned gjenåpner (kontoen deres).",
		"Type to search for an employee" : "Skriv for å søke etter en medarbeider",
		"Type, start date, and end date are required" : "Type, startdato og sluttdato er påkrevd",
		"Type, start_date, and end_date are required" : "Type, startdato og sluttdato er påkrevd",
		"Type: %1$s" : "Type: %1$s (post)",
		"Typical number of work days each week for this model (e.g. 4 for a four-day week). Used for model-based vacation entitlement calculations." : "Typisk antall arbeidsdager hver uke for denne modellen (f.eks. 4 for en firedagersuke). Brukes til modellbaserte ferieberegninger.",
		"Typical value in Germany: 31 March (month 3, day 31). If that day does not exist in a month (e.g. 31 February), the last day of that month is used automatically." : "Vanlig verdi i Tyskland: 31. mars (måned 3, dag 31). Hvis den dagen ikke finnes i en måned (f.eks. 31. februar), brukes den siste dagen i den måneden automatisk.",
		"UE" : "UE",
		"Unable to load compliance data." : "Kan ikke laste inn etterlevelsesdata.",
