		"Unauthorized" : "Uautorisert",
		"Unclassified travel time blocks submission" : "Uklassifisert reisetid blokkerer innsendingen",
		"Under GDPR, you have the right to access your personal data. You can export all your time tracking data at any time." : "I henhold til GDPR har du rett til å få tilgang til dine personlige data. Du kan når som helst eksportere alle tidsregistreringsdataene dine.",
		"Under the GDPR you can request a copy of your data, correction of inaccuracies or deletion of your records. ArbeitszeitCheck provides a self-service data export and deletion request inside the app under \"My settings\" → \"Data and privacy\"." : "Under GDPR kan be om en kopi av dataene dine, retting av unøyaktigheter eller sletting av postene dine. ArbeitszeitCheck tilbyr selvbetjent dataeksport og sletteforespørsel i appen under \"Mine innstillinger\" → \"Data og personvern\".",
