		"Up to 1 employee may be re-resolved by this change." : "Opptil 1 medarbeider kan bli gjenløst av denne endringen.",
		"Up to 5 digits." : "Opptil 5 sifre.",
		"Up to 7 digits. Saved with Save on this page." : "Inntil 7 siffer. Lagret med Lagre på denne siden.",
		"Up to 7 digits. Saved with “Save all settings”." : "Opptil 7 siffer. Lagres med «Lagre alle innstillinger».",
		"Up to 8 digits. Required for DATEV export of this employee." : "Opptil 8 sifre. Kreves for DATEV-eksport av denne ansatte.",
		"Up to two decimal places are allowed, e.g. 1.5 or 4.25 — comma or dot both work." : "Opptil to desimaler er tillatt, f.eks. 1,5 eller 4,25 — både komma og punktum fungerer.",
		"Up to {n} employees may be re-resolved by this change." : "Opptil {n} medarbeidere kan bli gjenløst av denne endringen.",
