		"Update time entry" : "Oppdater tidsregistrering",
		"Updated" : "Oppdatert",
		"Updated %1$d, failed %2$d." : "%1$d oppdatert, %2$d mislyktes.",
		"Updates whenever your calendar app refreshes the subscription." : "Oppdateres når kalenderappen oppdaterer abonnementet.",
		"Upper bound: counts users without an L1\/L2\/L3 override at all. Some users may still be served by a higher layer." : "Øvre grense: teller brukere uten L1\/L2\/L3-overstyring i det hele tatt. Noen brukere kan fortsatt dekkes av et høyere nivå.",
		"Upper limit of daily working time in hours. German labor law (ArbZG) allows 8 hours normally, up to 10 in special cases." : "Øvre grense for daglig arbeidstid i timer. Tysk arbeidslovgivning (ArbZG) tillater normalt 8 timer, opptil 10 i spesielle tilfeller.",
		"Upper limit of daily working time in hours. The suggested default comes from the selected country profile (Germany ArbZG: up to 10; Austria AZG: up to 12). Changing the country does not overwrite a value you already set." : "Øvre grense for daglig arbeidstid i timer. Den foreslåtte standarden kommer fra den valgte landsprofilen (Tyskland ArbZG: opptil 10; Østerrike AZG: opptil 12). Bytte av land overskriver ikke en verdi du allerede har satt.",
		"Upper limit of daily working time in hours. The suggested default comes from the selected country profile (Germany ArbZG: up to 10; Austria AZG: up to 12; Switzerland ArG: up to 10). Changing the country does not overwrite a value you already set." : "Øvre grense for daglig arbeidstid i timer. Foreslått standard kommer fra den valgte landsprofilen (Tyskland ArbZG: opptil 10; Østerrike AZG: opptil 12; Sveits ArG: opptil 10). Landbytte overskriver ikke en verdi du allerede har satt.",
		"Uri" : "Uri",
		"Use \"Start Break\" and \"End Break\" to record your breaks. The system will remind you if you forget." : "Bruk «Start pause» og «Avslutt pause» for å registrere pausene dine. Systemet minner hvis glemmer det.",
		"Use 0–366 in steps of 0.5 (for example 25 or 25.5)." : "Bruk 0–366 i trinn på 0,5 (for eksempel 25 eller 25,5).",
		"Use 7.7" : "Bruk 7,7",
		"Use 7.7 (= 38.5 ÷ 5) so open day balances convert fairly." : "Bruk 7,7 (= 38,5 ÷ 5), så åpne dagsaldoer konverteres rettferdig.",
		"Use ArbeitszeitCheck teams for approvals" : "Bruk ArbeitszeitCheck-team til godkjennelser",
		"Use ArbeitszeitCheck teams instead of Nextcloud groups" : "Bruk ArbeitszeitCheck-team i stedet for Nextcloud-grupper",
		"Use a compact date range. The maximum window is 365 days and feeds above 5000 approved absences are rejected." : "Bruk et kompakt datointervall. Maksimalt vindu er 365 dager, og feeder med over 5000 godkjente fravær avvises.",
		"Use app teams setting saved" : "Innstillingen for app-team er lagret",
		"Use fixed value, automatic from schedule, or tariff rule. Exception mode requires a reason." : "Bruk fast verdi, automatisk fra arbeidsplanen eller tariffregel. Unntaksmodus krever en grunn.",
		"Use global default state" : "Bruk global standarddelstat",
		"Use organisation default" : "Bruk organisasjonens standard",
		"Use quick actions and role-based status sections in one place." : "Bruk hurtige handlinger og rollebaserede statussektioner på ét sted.",
		"Use suggested version" : "Bruk foreslått versjon",
		"Use the \"Clock In\" button to start tracking your work time. When you finish, click \"Clock Out\" to stop." : "Bruk knappen «Stemple inn» for å begynne å registrere arbeidstiden din. Når du er ferdig, klikker du «Stemple ut» for å stoppe.",
		"Use the arrow keys to move between exports, then press Enter or Space to select." : "Bruk piltastene for å flytte mellom eksporter, og trykk deretter Enter eller mellomrom for å velge.",
		"Use the date picker — only ISO YYYY-MM-DD dates are accepted." : "Bruk datovelgeren — bare ISO-datoer YYYY-MM-DD godtas.",
		"Use the same form for old vacation, sick leave, migration records, and future requests. Closed months stay protected and cannot be changed unless an administrator reopens them." : "Bruk det samme skjemaet for gamle ferie-, sykefraværs- og migreringsregistreringer samt fremtidige forespørsler. Lukkede måneder forblir beskyttet og kan ikke endres med mindre en administrator gjenåpner dem.",
		"Use these buttons to track your working hours. Click \"Clock In\" when you start working and \"Clock Out\" when you finish." : "Bruk disse knappene for å registrere arbeidstiden din. Klikk «Stemple inn» når du begynner å arbeide, og «Stemple ut» når du er ferdig.",
		"Use these settings to prevent users from staying in an open break state for many hours by accident." : "Bruk disse innstillingene for å hindre at brukere ved en feil blir værende i åpen pausetilstand i mange timer.",
		"Use this form to edit your time entry. The form will automatically check compliance with German labor law requirements." : "Bruk dette skjemaet for å redigere tidsregistreringen din. Skjemaet kontrollerer automatisk etterlevelse av tyske arbeidsrettskrav.",
		"Use this form to record when you worked. Fill in the date, start time, end time, and optionally break times. The form will automatically check compliance with German labor law requirements." : "Bruk dette skjemaet for å registrere når jobbet. Fyll ut dato, starttid, sluttid og eventuelle pausetider. Skjemaet kontrollerer automatisk etterlevelse av tyske arbeidsrettskrav.",
		"Use this when the contract does not match any shared working time model. The weekly and daily hours below apply only to this employee." : "Bruk denne når kontrakten ikke samsvarer med noen delt arbeidstidsmodell. Uke- og dagtimene nedenfor gjelder bare denne ansatte.",
		"Use valid email addresses separated by commas. Duplicates are removed automatically." : "Bruk gyldige e-postadresser atskilt med komma. Dubletter fjernes automatisk.",
		"Use “Rotate link” on an existing row to replace its URL. Calendar apps with the old link stop updating immediately." : "Bruk « Roter lenke » på en eksisterende rad for å erstatte URL-en. Kalenderapper med den gamle lenken slutter å oppdatere umiddelbart.",
		"Used" : "Brukt",
		"Used for statutory holidays and compliance when no specific region is configured for employees or teams." : "Brukes til lovpålagte helligdager og etterlevelse når det ikke er konfigurert en spesifikk region for ansatte eller team.",
		"Used for statutory holidays and compliance when no specific region is configured for employees." : "Brukes til lovpålagte helligdager og etterlevelse når det ikke er konfigurert en spesifikk region for ansatte.",
		"Used for statutory holidays and compliance when no specific state is configured for employees or teams." : "Brukes til lovpålagte helligdager og etterlevelse når ingen spesifikk delstat er konfigurert for medarbeidere eller team.",
		"Used only when converting days ↔ hours. Day-to-day booking still follows each person’s work schedule." : "Brukes bare ved konvertering mellom dager ↔ timer. Daglig booking følger fortsatt hver persons arbeidstidsmodell.",
		"Used this year" : "Brukt i år",
		"Used when no team policy, model default, or individual rule applies. This is the safety net for new employees." : "Brukes når ingen teampolicy, modellstandard eller individuell regel gjelder. Dette er sikkerhetsnettet for nye medarbeidere.",
