		"Vacation year mode updated. Open vacation balances were refreshed for %s people (%s could not be refreshed — check employment data)." : "Ferieårsmodus oppdatert. Åpne feriesaldoer ble oppdatert for %s personer (%s kunne ikke oppdateres — sjekk ansettelsesdata).",
