		"Warning" : "Advarsel",
		"Warning: 6-month average weekly working hours (%.2f h\/week) exceeds 48 hours\/week (ArbZG §3)." : "Advarsel: 6-måneders gjennomsnitlig ukentlig arbeidstid (%.2f t\/uke) overstiger 48 timer\/uke (ArbZG §3).",
		"Warning: 6-month average working hours (%.2f h\/day) exceeds 8 hours\/day. 10-hour days are only allowed if the average does not exceed 8 hours (ArbZG §3)." : "Advarsel: 6-måneders gjennomsnittlig arbeidstid (%.2f t\/dag) overstiger 8 timer\/dag. 10-timersdager er kun tillatt hvis gjennomsnittet ikke overstiger 8 timer (ArbZG §3).",
		"Warning: average weekly working hours over %1$d weeks (%2$.2f h\/week) exceed %3$d hours\/week (%4$s)." : "Advarsel: gjennomsnittlig ukentlig arbeidstid over %1$d uker (%2$.2f t\/uke) overstiger %3$d timer\/uke (%4$s).",
		"Warning: average working hours over %1$d weeks (%2$.2f h\/day) exceed %3$d hours\/day. Longer days are only allowed if the average stays within the limit (%4$s)." : "Advarsel: gjennomsnittlig arbeidstid over %1$d uker (%2$.2f t\/dag) overstiger %3$d timer\/dag. Lengre dager er bare tillatt hvis gjennomsnittet holder seg innenfor grensen (%4$s).",
		"Warning: employee list was truncated; contact support." : "Advarsel: medarbeiderlisten ble avkortet; kontakt support.",
		"Warning: more than one organisation default is active on the same date. Resolution falls back to the latest row and emits a degraded flag. Please remove the conflicting row." : "Advarsel: mer enn én organisasjonsstandard er aktiv på samme dato. Oppløsningen faller tilbake til den siste raden og sender ut et degradert flagg. Fjern den motstridende raden.",
		"Warning: this rule currently matches nobody." : "Advarsel: denne regelen gjelder for øyeblikket ingen.",
		"Warning: working hours in the current week (%1$.2f h) exceed the absolute weekly maximum of %2$d hours (%3$s)." : "Advarsel: arbeidstid i gjeldende uke (%1$.2f t) overstiger det absolutte ukentlige maksimumet på %2$d timer (%3$s).",
		"Warnings" : "Advarsler",
		"Wed" : "Ons",
		"Wednesday" : "onsdag",
		"Week" : "Uke",
		"Week Start" : "Ukestart",
