		"Year must be between 1900 and 2100. You entered %s." : "Årstallet må være mellom 1900 og 2100. Du oppga %s.",
		"Year must be between 1900 and 2100. You entered {year}." : "Året må være mellom 1900 og 2100. Du oppga {year}.",
